// Tutorial cards filtering (cards and menus are generated by docs/extensions/filterlist.py).
// Plain JS: Sphinx no longer bundles jQuery, which used to arrive with sphinx-hoverxref.

// Split a card's comma-separated data-tags attribute into a list of tags
function getCardTags(card) {
    return (card.getAttribute("data-tags") || "")
        .split(",")
        .map((tag) => tag.trim()) // Get rid of whitespace
        .filter((tag) => tag !== ""); // Make sure there are no empty tags
}

// Create a sorted list of all unique tags that appear in the cards
function getUniqueTags() {
    let tagSet = new Set();
    document.querySelectorAll(".card-container").forEach(function (card) {
        getCardTags(card).forEach((tag) => tagSet.add(tag));
    });
    return Array.from(tagSet).sort();
}

// Get all of the tutorial group names, in order of appearance
function getUniqueGroups() {
    let groupSet = new Set();
    document.querySelectorAll(".card-container").forEach(function (card) {
        let group = (card.getAttribute("data-group") || "").trim();
        if (group !== "") {
            groupSet.add(group);
        }
    });
    return Array.from(groupSet);
}

// Append a menu button to every element matching `menuSelector`
function addMenuButton(menuSelector, className, dataAttr, value, label) {
    document.querySelectorAll(menuSelector).forEach(function (menu) {
        let button = document.createElement("div");
        button.className = className;
        button.setAttribute(dataAttr, value);
        button.textContent = label;
        menu.appendChild(button);
    });
}

// Create the tag button menu
function createMenu() {
    getUniqueTags().forEach(function (tag) {
        let displayName = tag.replace(/-/g, " "); // Replace dashes with spaces
        addMenuButton(
            ".filter-menu",
            "filter filter-btn",
            "data-tag",
            tag,
            displayName,
        );
    });
}

// Populate the tab menu for tutorial groups
function populateTabs() {
    getUniqueGroups().forEach(function (group) {
        addMenuButton(".tab-menu", "tab tab-btn", "data-group", group, group);
    });
}

let selectedTagSet = new Set();
let selectedGroupSet = new Set();

// Filter cards based on both tags and groups
function filterCards() {
    document.querySelectorAll(".card-container").forEach(function (card) {
        let cardTags = getCardTags(card);
        let groupName = card.getAttribute("data-group");

        let matchesTags =
            selectedTagSet.size === 0 ||
            [...selectedTagSet].every((tag) => cardTags.includes(tag));
        // A card only has one group, so multi-select here means "matches any of
        // the selected groups" (OR), unlike tags where a card can carry many tags (AND).
        let matchesGroup =
            selectedGroupSet.size === 0 || selectedGroupSet.has(groupName);

        card.classList.toggle("hidden", !(matchesTags && matchesGroup));

        // Hide the group name on the cards when a single group is selected
        card.querySelectorAll(".model-group-name").forEach(function (name) {
            name.classList.toggle("hidden", selectedGroupSet.size === 1);
        });
    });
}

// Shared multi-select logic of the tag and group menus.
// "all" clears the selection; otherwise the clicked button is toggled.
function handleSelection(
    button,
    menuSelector,
    buttonSelector,
    attr,
    selectedSet,
    allClass,
) {
    let menu = button.closest(menuSelector);
    let value = button.getAttribute(attr);

    if (value === "all") {
        if (!menu.classList.contains(allClass)) {
            selectedSet.clear();
            menu.classList.add(allClass);
            document
                .querySelectorAll(buttonSelector)
                .forEach((btn) => btn.classList.remove("selected"));
        }
    } else if (selectedSet.has(value)) {
        selectedSet.delete(value);
        button.classList.remove("selected"); // Deselect button
        if (selectedSet.size === 0) {
            menu.classList.add(allClass);
        }
    } else {
        menu.classList.remove(allClass);
        selectedSet.add(value);
        button.classList.add("selected"); // Highlight selected button
    }

    filterCards(); // Trigger filtering immediately
}

document.addEventListener("click", function (event) {
    let tagButton = event.target.closest(".filter-btn");
    if (tagButton) {
        handleSelection(
            tagButton,
            ".filter-menu",
            ".filter-btn",
            "data-tag",
            selectedTagSet,
            "all-tag-selected",
        );
        return;
    }
    let groupButton = event.target.closest(".tab-btn");
    if (groupButton) {
        handleSelection(
            groupButton,
            ".tab-menu",
            ".tab-btn",
            "data-group",
            selectedGroupSet,
            "all-group-selected",
        );
    }
});

function initTutorialFilters() {
    createMenu();
    populateTabs();
}

if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", initTutorialFilters);
} else {
    initTutorialFilters();
}

// Article header buttons (see docs/_templates/header-buttons.html).

// Toggle full screen mode
function toggleFullScreen() {
    if (document.fullscreenElement || document.webkitFullscreenElement) {
        (document.exitFullscreen || document.webkitExitFullscreen).call(
            document,
        );
    } else {
        let root = document.documentElement;
        (root.requestFullscreen || root.webkitRequestFullscreen).call(root);
    }
}

document.addEventListener("click", function (event) {
    if (event.target.closest(".scvi-fullscreen-button")) {
        toggleFullScreen();
    } else if (event.target.closest(".scvi-print-pdf")) {
        // Browsers offer to save the printed page as PDF
        window.print();
    }
});

// Swap the icon to match the current state, also when leaving with Esc
function updateFullScreenIcon() {
    let isFull = Boolean(
        document.fullscreenElement || document.webkitFullscreenElement,
    );
    document
        .querySelectorAll(".scvi-fullscreen-button i")
        .forEach(function (icon) {
            icon.classList.toggle("fa-expand", !isFull);
            icon.classList.toggle("fa-compress", isFull);
        });
}

document.addEventListener("fullscreenchange", updateFullScreenIcon);
document.addEventListener("webkitfullscreenchange", updateFullScreenIcon);
